 let api=null,active=false,world=null,role='owner',library=[],root=null,partner=null,letterMarks=[],decor=[],restore=new Map(),returnPosition=null,editingId=null,photoDraft=null,busy=false,clock=0,lastHint=0;
 const ownColliders=[],coatMeshes=[];pip.g.traverse(o=>{if(o.isMesh&&o.material===mat('#dba56d'))coatMeshes.push({mesh:o,original:o.material});});
