 function validate(w){if(!w||typeof w!=='object')return null;const v=blankWorld(safeText(w.name,55)||'Our little corner',themes[w.theme]?w.theme:'garden');v.id=safeText(w.id,80)||v.id;v.ownerName=safeText(w.ownerName,24)||'Me';v.guestName=safeText(w.guestName,24)||'My person';for(const k of ['coat','guestCoat'])if(/^#[0-9a-f]{6}$/i.test(w[k]))v[k]=w[k];v.memories=(Array.isArray(w.memories)?w.memories:[]).slice(0,12).map(m=>({id:safeText(m.id,80)||uid(),title:safeText(m.title,70)||'A little memory',text:safeText(m.text,5000),type:m.type==='postcard'?'postcard':'letter',photo:typeof m.photo==='string'&&m.photo.startsWith('data:image/jpeg;base64,')&&m.photo.length<300000?m.photo:null,x:Math.max(-26,Math.min(26,Number(m.x)||0)),z:Math.max(-26,Math.min(26,Number(m.z)||0))}));v.gift=w.gift===true;v.props=(Array.isArray(w.props)?w.props:[]).filter(q=>q&&propKinds[q.k]).slice(0,60).map(q=>({k:q.k,x:Math.max(-24,Math.min(24,Number(q.x)||0)),z:Math.max(-24,Math.min(24,Number(q.z)||0)),r:Number(q.r)||0}));v.colors={};for(const k of ['ground','leaf','water','sky'])if(/^#[0-9a-f]{6}$/i.test(w.colors?.[k]))v.colors[k]=w.colors[k];v.expires=Number(w.expires)>0?Number(w.expires):0;v.found=(Array.isArray(w.found)?w.found:[]).filter(id=>v.memories.some(m=>m.id===id));return v;}
 try{const raw=JSON.parse(localStorage.getItem(key));if(Array.isArray(raw))library=raw.map(validate).filter(w=>w&&!(w.expires&&w.expires<Date.now())).slice(0,6);}catch{}
